mapper.select:
select id, member_no as memberNo, member_name as memberName, status
from member
where member_no = #{memberNo}

mapper.update:
update member_process_step
set status = #{status},
    end_time = #{endTime},
    elapsed_ms = #{elapsedMs},
    error_code = #{errorCode},
    error_type = #{errorType},
    error_message = #{errorMessage}
where process_id = #{processId}
  and step_id = #{stepId}
